                [2 if top[i][c] != 0 and bottom[i][c] != 0 else 0
                 for c in range(w)]
                for i in range(n)
            ]

    # A solid nonzero column separates left and right panels.
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            left = c
            right = w - c - 1
            n = min(left, right)
            return [
                [2 if grid[r][c - n + j] != 0 and grid[r][c + 1 + j] != 0 else 0
                 for j in range(n)]
                for r in range(h)
            ]

