def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = []

    for r, row in enumerate(grid):
        color = row[0]
        if color and all(x == color for x in row):
            if all(grid[i][j] != color for i in range(h) if i != r for j in range(w)):
                separators.append(("row", r))

    for c in range(w):
        color = grid[0][c]
        if color and all(grid[i][c] == color for i in range(h)):
            if all(grid[i][j] != color for i in range(h) for j in range(w) if j != c):
                separators.append(("col", c))

    if not separators:
        return []

    axis, pos = separators[0]
    if axis == "row":
        top, bottom = grid[:pos], grid[pos + 1:]
        n = min(len(top), len(bottom))
        return [[2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(w)] for i in range(n)]

    left, right = pos, w - pos - 1
    n = min(left, right)
    return [[2 if grid[i][pos - n + j] != 0 and grid[i][pos + 1 + j] != 0 else 0
             for j in range(n)] for i in range(h)]
